    public boolean isValidSudoku(char[][] board) {
        for (int r = 0; r < 9; r++) {
            Set<Character> seen = new HashSet<>();
            for (int c = 0; c < 9; c++) {
                if (board[r][c] != '.' && !seen.add(board[r][c])) return false;
            }
        }
        for (int c = 0; c < 9; c++) {
            Set<Character> seen = new HashSet<>();
            for (int r = 0; r < 9; r++) {
                if (board[r][c] != '.' && !seen.add(board[r][c])) return false;
            }
        }
        for (int b = 0; b < 9; b++) {
            Set<Character> seen = new HashSet<>();
            for (int r = 0; r < 3; r++) {
                for (int c = 0; c < 3; c++) {
                    char ch = board[(b / 3) * 3 + r][(b % 3) * 3 + c];
                    if (ch != '.' && !seen.add(ch)) return false;
                }
            }
        }
        return true;
    }
}

